#!/usr/bin/env python3
"""Compute ground truth for CSX-254_Q1 from the local CSX-254 package."""

from __future__ import annotations

import json
import re
from pathlib import Path
from typing import Any, Callable


EVENT_ID = "CSX-254"
TASK_ID = "CSX-254_Q1"
TARGET_FAMILY = "threshold_ledger"
TASK_DIR = Path(__file__).resolve().parent

SOURCE_FILES = {
    "anchor": "data/event_reports/event_reports_003_Locked_event_anchor_2019-2020_Australian_Black_Summer_heat-drought-fire-smoke_event.json",
    "nasa_report": "data/event_reports/event_reports_001_Locked_anchor_NASA_Earth_Observatory.html",
    "open_meteo": "data/physical_hazard/physical_hazard_001_Open-Meteo_historical_daily_point_sample.json",
    "sentinel2_dnbr": "data/physical_hazard/physical_hazard_006_Sentinel-2_SR_Harmonized_dNBR.json",
}


def package_dir() -> Path:
    return Path(__file__).resolve().parents[3] / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID


def read_json(root: Path, relative_path: str) -> Any:
    return json.loads((root / relative_path).read_text(encoding="utf-8"))


def read_text(root: Path, relative_path: str) -> str:
    return (root / relative_path).read_text(encoding="utf-8", errors="ignore")


def longest_run(rows: list[dict[str, Any]], predicate: Callable[[dict[str, Any]], bool]) -> dict[str, Any]:
    best: list[dict[str, Any]] = []
    current: list[dict[str, Any]] = []
    for row in rows:
        if predicate(row):
            current.append(row)
        else:
            if len(current) > len(best):
                best = current
            current = []
    if len(current) > len(best):
        best = current
    return {
        "days": len(best),
        "start": best[0]["date"] if best else None,
        "end": best[-1]["date"] if best else None,
    }


def has_text(pattern: str, text: str) -> bool:
    return bool(re.search(pattern, text, flags=re.IGNORECASE))


def rubric() -> dict[str, Any]:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "Requested JSON shape",
                "points": 3,
                "description": (
                    "Returns compact JSON with target_family, metrics, gates, answer, "
                    "rejected_alternative, and one ledger-tied computed_consequence."
                ),
                "partial_credit": "Give partial credit for minor key-name differences that preserve the same fields.",
            },
            {
                "name": "Metric extraction",
                "points": 5,
                "description": (
                    "Reports longest_hot_dry_run_days = 15, longest_very_hot_dry_windy_run_days = 2, "
                    "peak_tmax_c = 46.0, and sentinel2_dnbr_mean = 0.156 within tolerance."
                ),
                "partial_credit": "Give partial credit for two or three correct metrics or recognizable threshold states.",
            },
            {
                "name": "Predicate and formula use",
                "points": 3,
                "description": (
                    "Applies the hot-dry, very-hot-dry-windy, and burn-change threshold definitions exactly."
                ),
                "partial_credit": "Give partial credit for correct qualitative gates with one threshold or inequality error.",
            },
            {
                "name": "Gate ledger and final label",
                "points": 4,
                "description": (
                    "Sets all five gates to true and returns compound_fire_weather_smoke_threshold_pass "
                    "using the all-gates decision rule."
                ),
                "partial_credit": "Give partial credit for the correct label with one missing gate or correct gates with a mislabeled answer.",
            },
            {
                "name": "Text-gate separation",
                "points": 2,
                "description": (
                    "Treats pyrocumulonimbus or firestorm support and stratospheric-smoke support as narrative gates, "
                    "not as values inferred from dNBR."
                ),
                "partial_credit": "Give partial credit for finding the right flags but blurring their source.",
            },
            {
                "name": "Rejected alternative",
                "points": 2,
                "description": (
                    "Rejects heat-only, rain/flood, or slow vegetation-change alternatives through the failed ledger logic."
                ),
                "partial_credit": "Give partial credit for rejecting one weaker alternative without tying it to a gate.",
            },
            {
                "name": "Bounded computed consequence",
                "points": 1,
                "description": (
                "Keeps the final sentence tied to the threshold result and avoids extra loss totals, "
                "national representativeness claims, action claims, or broad disaster explanation."
                ),
                "partial_credit": "No credit if the answer turns into an action note or broad disaster explanation.",
            },
        ],
    }


def build_daily_rows(open_meteo: dict[str, Any]) -> list[dict[str, Any]]:
    daily = open_meteo["daily"]
    rows = []
    for index, date in enumerate(daily["time"]):
        rows.append(
            {
                "date": date,
                "tmax_c": float(daily["temperature_2m_max"][index]),
                "precip_mm": float(daily["precipitation_sum"][index]),
                "wind_kmh": float(daily["wind_speed_10m_max"][index]),
            }
        )
    return rows


def main() -> None:
    root = package_dir()
    anchor = read_json(root, SOURCE_FILES["anchor"])
    open_meteo = read_json(root, SOURCE_FILES["open_meteo"])
    dnbr = read_json(root, SOURCE_FILES["sentinel2_dnbr"])
    nasa_text = read_text(root, SOURCE_FILES["nasa_report"])

    rows = build_daily_rows(open_meteo)
    peak_tmax_row = max(rows, key=lambda row: row["tmax_c"])
    hot_dry = lambda row: row["tmax_c"] >= 40.0 and row["precip_mm"] < 1.0
    very_hot_dry_windy = (
        lambda row: row["tmax_c"] >= 45.0 and row["precip_mm"] < 1.0 and row["wind_kmh"] >= 30.0
    )

    hot_dry_run = longest_run(rows, hot_dry)
    vhdw_run = longest_run(rows, very_hot_dry_windy)
    dnbr_mean = round(float(dnbr["stats"]["sentinel2_dnbr_mean"]), 3)

    metrics = {
        "longest_hot_dry_run_days": hot_dry_run["days"],
        "longest_very_hot_dry_windy_run_days": vhdw_run["days"],
        "peak_tmax_c": round(peak_tmax_row["tmax_c"], 1),
        "sentinel2_dnbr_mean": dnbr_mean,
    }
    gates = {
        "hot_dry_run_ge_10": metrics["longest_hot_dry_run_days"] >= 10,
        "vhdw_run_ge_2": metrics["longest_very_hot_dry_windy_run_days"] >= 2,
        "burn_change_mean_gt_0_10": dnbr_mean > 0.10,
        "pyrocb_or_firestorm_text": has_text(
            r"pyrocumulonimbus|fire-triggered clouds?|firestorms?", nasa_text
        ),
        "stratospheric_smoke_text": has_text(r"15 to 19 kilometers|stratosphere", nasa_text),
    }
    answer = (
        "compound_fire_weather_smoke_threshold_pass"
        if all(gates.values())
        else "compound_fire_weather_smoke_threshold_fail"
    )

    primary_gt = {
        "target_family": TARGET_FAMILY,
        "metrics": metrics,
        "gates": gates,
        "answer": answer,
        "rejected_alternative": "heat_only_or_vegetation_only",
        "computed_consequence": (
            "The threshold ledger supports a fire-weather-to-smoke cascade rather than a heat-only, "
            "rain/flood, or slow vegetation-change diagnosis."
        ),
    }

    output = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "target_family": TARGET_FAMILY,
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "event": {
            "event_name": "2019-2020 Australian Black Summer heat-drought-fire-smoke event",
            "event_window": anchor["temporal_window"],
            "hazard_family": "wildfire_heat_drought_smoke",
        },
        "primary_gt": primary_gt,
        "key_values": {
            "hot_dry_definition": "Tmax >= 40.0 C and precipitation < 1.0 mm",
            "very_hot_dry_windy_definition": "Tmax >= 45.0 C and precipitation < 1.0 mm and wind >= 30.0 km/h",
            "hot_dry_run_window": {"start": hot_dry_run["start"], "end": hot_dry_run["end"]},
            "very_hot_dry_windy_run_window": {"start": vhdw_run["start"], "end": vhdw_run["end"]},
            "peak_tmax_date": peak_tmax_row["date"],
            "sentinel2_dnbr_max": round(float(dnbr["stats"]["sentinel2_dnbr_max"]), 3),
            "text_gate_patterns": {
                "pyrocb_or_firestorm_text": "pyrocumulonimbus|fire-triggered clouds|firestorms",
                "stratospheric_smoke_text": "15 to 19 kilometers|stratosphere",
            },
        },
        "decision_rule": "all five gates true",
        "numeric_tolerances": {
            "integer_counts": 0,
            "peak_tmax_c": 0.1,
            "sentinel2_dnbr_mean": 0.005,
        },
        "rubric": rubric(),
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": list(SOURCE_FILES.values()),
        },
    }

    (TASK_DIR / "computed_gt.json").write_text(
        json.dumps(output, indent=2, ensure_ascii=True, sort_keys=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
